export default function install(app){const mount=app.getMount('trail-elevation-profile');const previous={height:mount.style.height,minHeight:mount.style.minHeight,maxHeight:mount.style.maxHeight,boxSizing:mount.style.boxSizing};mount.style.height='calc(clamp(180px, 28vh, 230px) - 56px)';mount.style.maxHeight='calc(clamp(180px, 28vh, 230px) - 56px)';mount.style.minHeight='0';mount.style.boxSizing='border-box';app.onCleanup(()=>{for(const [key,value] of Object.entries(previous))mount.style[key]=value;});}